// Compute date range for the past week
const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

// Format as ISO 8601 for GitHub API
const since = oneWeekAgo.toISOString();
const until = now.toISOString();

// Human-readable dates
const weekStart = oneWeekAgo.toISOString().split('T')[0];
const weekEnd = now.toISOString().split('T')[0];

return {
  since: since,
  until: until,
  weekStart: weekStart,
  weekEnd: weekEnd
};

// Aggregate data and build Claude prompt
const items = $input.all();

// Item 0: commits, Item 1: issues, Item 2: PRs
const commits = items[0]?.json || [];
const issues = items[1]?.json || [];
const prs = items[2]?.json || [];

const config = $('Configuration').item.json;
const dates = $('Compute Date Range').item.json;
const lang = config.language === 'FR' ? 'French' : 'English';

// Summarize commits
const commitList = commits.slice(0, 20).map(c => {
  const msg = (c.commit?.message || '').split('\n')[0].substring(0, 80);
  const author = c.commit?.author?.name || c.author?.login || 'unknown';
  return `- ${msg} (${author})`;
}).join('\n') || '(no commits this week)';

// Summarize issues
const issueList = issues.filter(i => !i.pull_request).slice(0, 10).map(i => {
  return `- #${i.number} ${i.title} (closed by ${i.closed_by?.login || 'unknown'})`;
}).join('\n') || '(no issues closed)';

// Summarize PRs
const prList = prs.filter(p => p.merged_at).slice(0, 10).map(p => {
  return `- #${p.number} ${p.title} (merged by ${p.merged_by?.login || 'unknown'})`;
}).join('\n') || '(no PRs merged)';

// Count merged PRs that were merged this week
const mergedThisWeek = prs.filter(p => {
  if (!p.merged_at) return false;
  const merged = new Date(p.merged_at);
  return merged >= new Date(dates.since);
});

const prompt = `You are a technical writer generating a weekly development summary for the ${config.repo_owner}/${config.repo_name} repository.

Write a narrative summary in ${lang} covering ${dates.weekStart} to ${dates.weekEnd}.

## Data

### Commits (${commits.length} total)
${commitList}

### Closed Issues (${issueList.split('\n').length - 1} closed)
${issueList}

### Merged PRs (${mergedThisWeek.length} this week)
${prList}

## Format

Generate a Markdown summary with these sections:

### 📊 Weekly Overview
One paragraph: key themes and overall activity level.

### 🚀 Highlights
2-3 most important changes this week.

### 📝 Commits
Summarize the pattern of commits (not a list — describe what areas saw activity).

### 🔧 Issues & Fixes
What got resolved.

### 🔀 Pull Requests Merged
List with brief descriptions.

### 🎯 Looking Ahead
What seems to be in progress based on open PRs/commits.

Keep it concise — 300-500 words. Use emoji section headers. No markdown headings above H3.`;

return {
  prompt: prompt,
  repo: `${config.repo_owner}/${config.repo_name}`,
  weekStart: dates.weekStart,
  weekEnd: dates.weekEnd,
  stats: {
    commits: commits.length,
    issuesClosed: issueList.split('\n').length - 1,
    prsMerged: mergedThisWeek.length
  }
};

// Extract Claude's response
const claudeResponse = $input.item.json;
const summaryText = claudeResponse.content?.[0]?.text || claudeResponse.content || JSON.stringify(claudeResponse);

const context = $('Build Claude Prompt').item.json;

// Build Slack/Discord formatted message
const message = {
  text: `📊 *Weekly Dev Summary: ${context.repo}*\n_${context.weekStart} → ${context.weekEnd}_\n\n${summaryText}\n\n---\n_Generated by Claude Code + n8n_`
};

// For Slack, use blocks
const slackBlocks = {
  blocks: [
    {
      type: "header",
      text: { type: "plain_text", text: `📊 Weekly Dev Summary: ${context.repo}` }
    },
    {
      type: "context",
      elements: [{ type: "mrkdwn", text: `${context.weekStart} → ${context.weekEnd} | ⚡ by Claude + n8n` }]
    },
    {
      type: "section",
      text: { type: "mrkdwn", text: summaryText.substring(0, 3000) }
    },
    {
      type: "divider"
    },
    {
      type: "context",
      elements: [
        { type: "mrkdwn", text: `📝 ${context.stats.commits} commits · 🔧 ${context.stats.issuesClosed} issues · 🔀 ${context.stats.prsMerged} PRs merged` }
      ]
    }
  ]
};

return {
  slackMessage: slackBlocks,
  discordMessage: { content: message.text },
  plainText: summaryText
};
